<style>
.jp-bot{position:fixed;right:22px;bottom:22px;z-index:2147483000;font-family:Arial,sans-serif;color:#263547}.jp-bot *{box-sizing:border-box}.jp-bot button{cursor:pointer}.jp-bot #jp-avatar{width:76px;height:78px;border:0;background:linear-gradient(135deg,#f4f8fc,#aeb9cc);border-radius:28px;box-shadow:0 12px 28px #152b4555;position:relative;animation:jpFloat 3.5s ease-in-out infinite}.jp-face{display:flex;align-items:center;justify-content:center;flex-direction:column;width:60px;height:48px;background:#132f40;border-radius:18px;margin:auto;box-shadow:inset 0 0 10px #061928}.jp-eyes{color:#59e9ec;font-size:17px;white-space:nowrap;line-height:22px}.jp-smile{color:#59e9ec;font-size:22px;line-height:16px}.jp-label{position:absolute;bottom:-5px;left:29px;font-size:10px;border-radius:10px;background:#1ab394;color:white;padding:3px 5px}.jp-panel{position:absolute;right:0;bottom:90px;width:min(385px,calc(100vw - 28px));height:min(610px,calc(100vh - 120px));border-radius:20px;background:#fff;border:1px solid #e0e7ef;box-shadow:0 14px 45px #14233350;overflow:hidden;display:flex;flex-direction:column}.jp-panel[hidden]{display:none}.jp-head{flex-shrink:0;background:#253e50;color:white;padding:12px 14px;display:flex;align-items:center;justify-content:space-between;gap:8px}.jp-head small{display:block;font-size:10px;opacity:.8}.jp-head button{border:0;background:transparent;color:white;font-size:17px;padding:4px}.jp-messages{background:#f5f8fa;flex:1;min-height:90px;padding:13px;overflow:auto}.jp-msg{max-width:95%;margin:0 0 11px;padding:10px 13px;font-size:13px;line-height:1.5;border-radius:14px;white-space:pre-wrap;overflow-wrap:anywhere}.jp-ai{background:white;border:1px solid #e1e9ef;border-bottom-left-radius:3px}.jp-user{background:#d9f5ec;margin-left:auto;border-bottom-right-radius:3px}.jp-msg a{display:inline-block;margin:6px 4px 0 0;padding:5px 8px;border-radius:7px;background:#147b68;color:white;text-decoration:none}.jp-actions{padding:8px;display:flex;flex-wrap:wrap;gap:5px}.jp-actions button,.jp-actions a{font-size:11px;padding:6px 7px;color:#256358;border:1px solid #acdcd0;border-radius:12px;background:#f1fcf8;text-decoration:none}.jp-automation{padding:8px 12px;background:#f7fafc;border-top:1px solid #ebf0f4;font-size:11px}.jp-automation p{margin:4px 0 7px;line-height:1.35}.jp-automation button{border:0;border-radius:7px;background:#1a9e84;color:white;padding:7px 10px}.jp-bot #jp-form{display:flex;padding:9px;border-top:1px solid #e6edf1;gap:6px}.jp-bot #jp-question{flex:1;min-width:0;padding:9px;border:1px solid #d4dfe7;border-radius:9px;font-size:13px}.jp-bot #jp-send{background:#1ab394;border:0;border-radius:9px;color:white;padding:0 13px}.jp-bot #jp-send:disabled{opacity:.5}.jp-foot{padding:0 10px 8px;display:flex;justify-content:space-between;gap:8px;font-size:10px}.jp-foot small{color:#7c8792}.jp-foot a{color:#168572}@keyframes jpFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}@media(max-width:480px){.jp-bot{right:12px;bottom:12px}.jp-panel{bottom:84px}.jp-bot #jp-avatar{width:66px;height:70px}}
</style>
<script>
(function(){
function ready(){
 const root=document.getElementById('jp-bot');if(!root||root.dataset.initialized)return;root.dataset.initialized='1';
 const avatar=document.getElementById('jp-avatar'),panel=document.getElementById('jp-bot-panel'),messages=document.getElementById('jp-messages'),question=document.getElementById('jp-question'),send=document.getElementById('jp-send');
 let soundOn=localStorage.getItem('jpBotSound')!=='off', voiceOn=localStorage.getItem('jpBotVoice')==='on';
 const sound=document.getElementById('jp-sound'),voice=document.getElementById('jp-voice');
 function refresh(){sound.textContent=soundOn?'🔊':'🔇';voice.textContent=voiceOn?'🗣️':'🔕'}
 function beep(){if(!soundOn)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const c=new C(),o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=680;g.gain.setValueAtTime(.0001,c.currentTime);g.gain.exponentialRampToValueAtTime(.07,c.currentTime+.02);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+.16);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.17);o.onended=()=>c.close()}catch(e){}}
 function speak(t){if(!voiceOn||!window.speechSynthesis)return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='es-PE';u.rate=1;window.speechSynthesis.speak(u)}
 function add(text,who){const d=document.createElement('div');d.className='jp-msg '+(who==='user'?'jp-user':'jp-ai');d.textContent=text;messages.appendChild(d);messages.scrollTop=messages.scrollHeight;return d}
 function show(){panel.hidden=false;avatar.setAttribute('aria-expanded','true');beep();question.focus()}
 avatar.addEventListener('click',()=>{if(panel.hidden)show();else{panel.hidden=true;avatar.setAttribute('aria-expanded','false')}});
 document.getElementById('jp-close').addEventListener('click',()=>{panel.hidden=true;avatar.setAttribute('aria-expanded','false');if(window.speechSynthesis)window.speechSynthesis.cancel()});
 sound.addEventListener('click',()=>{soundOn=!soundOn;localStorage.setItem('jpBotSound',soundOn?'on':'off');refresh()});
 voice.addEventListener('click',()=>{voiceOn=!voiceOn;localStorage.setItem('jpBotVoice',voiceOn?'on':'off');if(!voiceOn&&window.speechSynthesis)window.speechSynthesis.cancel();refresh()});refresh();
 async function ask(q){if(!q.trim()||send.disabled)return;add(q,'user');question.value='';send.disabled=true;const waiting=add('Consultando a Gemini...','ai');try{const response=await fetch(root.dataset.chatUrl,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content||@json(csrf_token())},body:JSON.stringify({pregunta:q})});if(!response.ok)throw new Error('Consulta no disponible ('+response.status+')');const data=await response.json();waiting.textContent=data.respuesta||'Sin respuesta';if(data.aviso)add(data.aviso,'ai');for(const item of data.accesos||[]){const a=document.createElement('a');a.textContent='Abrir '+item.nombre;a.href=item.url;waiting.appendChild(document.createElement('br'));waiting.appendChild(a)}speak(data.respuesta||'')}catch(e){waiting.textContent='No se pudo consultar Gemini. '+e.message}finally{send.disabled=false;messages.scrollTop=messages.scrollHeight;question.focus()}}
 document.getElementById('jp-form').addEventListener('submit',e=>{e.preventDefault();ask(question.value)});
 root.querySelectorAll('[data-question]').forEach(b=>b.addEventListener('click',()=>ask(b.dataset.question)));
 const generate=document.getElementById('jp-generate');if(generate)generate.addEventListener('click',()=>{
  if(!window.confirm('¿Autorizas generar una PROPUESTA de horarios con el algoritmo actual? Esta operación puede reemplazar el borrador anterior, pero NO confirmará ni guardará asignaciones definitivas.'))return;
  const form=document.createElement('form');form.method='POST';form.action=root.dataset.generateUrl;const csrf=document.createElement('input');csrf.type='hidden';csrf.name='_token';csrf.value=@json(csrf_token());form.appendChild(csrf);document.body.appendChild(form);form.submit();
 });
 const propose=document.getElementById('jp-propose');if(propose)propose.addEventListener('click',()=>{
  const approved=window.confirm('¿Quieres ir a revisar los datos y preparar la propuesta con el algoritmo de asignación? No se guardarán horarios automáticamente.');if(approved)window.location.assign(root.dataset.assignmentUrl);
 });
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ready);else ready();
})();
</script>